int k = bits_per_key;
int m = n * k;
int bytes = (m + 7) / 8;
dst->assign(bytes, 0);

if (n == 0) {
    return;
}

// Calculate the number of hash functions needed
// k = (m/n) * ln(2)
// Since bits_per_key is already m/n, we use a standard approximation
// for the number of hash functions to minimize false positives.
int num_hashes = 0;
if (k > 0) {
    // Standard Bloom filter optimization: k = round(bits_per_key * ln(2))
    // ln(2) is approx 0.693
    num_hashes = static_cast<int>(k * 0.69314718056);
    if (num_hashes < 1) num_hashes = 1;
}

for (int i = 0; i < n; ++i) {
    const Slice& key = keys[i];
    // Use a double-hashing technique to simulate multiple hash functions
    // using only two hash values (h1 and h2).
    uint64_t h1 = leveldb::Hash(key.data(), key.size());
    uint64_t h2 = leveldb::Hash(key.data(), key.size(), h1);

    for (int j = 0; j < num_hashes; ++j) {
        uint64_t combined_hash = h1 + j * h2;
        uint64_t bit_pos = combined_hash % m;
        (*dst)[bit_pos / 8] |= (1 << (bit_pos % 8));
    }
}
// END_CODE

